public class ContactDomainService {

    private static final Integer QUERY_BATCH_SIZE = 1000;

    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> result = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        List<Id> idList = new List<Id>(accountIds);
        Integer total = idList.size();
        List<Contact> allContacts = new List<Contact>();

        for (Integer i = 0; i < total; i += QUERY_BATCH_SIZE) {
            Integer chunkSize = (total - i < QUERY_BATCH_SIZE) ? (total - i) : QUERY_BATCH_SIZE;
            List<Id> batch = new List<Id>();
            for (Integer j = 0; j < chunkSize; j++) {
                batch.add(idList[i + j]);
            }

            List<Contact> contacts = [
                SELECT Id, Email, AccountId
                FROM Contact
                WHERE AccountId IN :batch
            ];

            allContacts.addAll(contacts);
        }

        for (Contact c : allContacts) {
            if (String.isBlank(c.Email)) {
                continue;
            }

            String email = c.Email.trim();
            Integer atIdx = email.lastIndexOf('@');
            if (atIdx < 0 || atIdx == email.length() - 1) {
                continue;
            }

            String domain = email.substring(atIdx + 1).toLowerCase();
            if (String.isBlank(domain)) {
                continue;
            }

            if (!result.containsKey(domain)) {
                result.put(domain, new List<Contact>());
            }
            result.get(domain).add(c);
        }

        return result;
    }
}
