```apex
public class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // Validate maxRows
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // Validate fields list
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty.');
        }

        // Resolve object (case-insensitive)
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name must not be blank.');
        }
        Schema.SObjectType objType = resolveObject(objectApiName);
        if (objType == null) {
            throw new SearchException('Object not found: ' + objectApiName);
        }

        // Build case-insensitive field map
        Map<String, Schema.SObjectField> fieldMap = buildFieldMap(objType);

        // Validate and resolve SELECT fields
        Set<String> selectFields = new Set<String>{ 'Id' };
        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('Field name in fields list must not be blank.');
            }
            Schema.SObjectField sf = fieldMap.get(f.toLowerCase());
            if (sf == null) {
                throw new SearchException('Field not found on object [' + objectApiName + ']: ' + f);
            }
            selectFields.add(sf.getDescribe().getName());
        }

        // Validate and resolve filter fields
        Map<String, Object> resolvedFilters = new Map<String, Object>();
        if (filters != null) {
            for (String key : filters.keySet()) {
                if (String.isBlank(key)) {
                    throw new SearchException('Filter field name must not be blank.');
                }
                Schema.SObjectField sf = fieldMap.get(key.toLowerCase());
                if (sf == null) {
                    throw new SearchException('Filter field not found on object [' + objectApiName + ']: ' + key);
                }
                if (!sf.getDescribe().isAccessible()) {
                    throw new SearchException('Field cannot be filtered: ' + key);
                }
                resolvedFilters.put(sf.getDescribe().getName(), filters.get(key));
            }
        }

        // Validate and resolve order-by field
        String resolvedOrderBy = null;
        if (String.isNotBlank(orderByField)) {
            Schema.SObjectField sf = fieldMap.get(orderByField.toLowerCase());
            if (sf == null) {
                throw new SearchException('Order-by field not found on object [' + objectApiName + ']: ' + orderByField);
            }
            if (!sf.getDescribe().isAccessible()) {
                throw new SearchException('Field cannot be sorted: ' + orderByField);
            }
            resolvedOrderBy = sf.getDescribe().getName();
        }

        // Build SOQL
        List<String> soqlParts = new List<String>();

        soqlParts.add('SELECT ' + String.join(new List<String>(selectFields), ', '));
        soqlParts.add('FROM ' + objType.getDescribe().getName());

        if (!resolvedFilters.isEmpty()) {
            List<String> conditions = new List<String>();
            for (String field : resolvedFilters.keySet()) {
                conditions.add(field + ' = ' + formatValue(resolvedFilters.get(field)));
            }
            soqlParts.add('WHERE ' + String.join(conditions, ' AND '));
        }

        if (resolvedOrderBy != null) {
            soqlParts.add('ORDER BY ' + resolvedOrderBy + ' ASC');
        }

        soqlParts.add('LIMIT ' + maxRows);
        soqlParts.add('WITH SECURITY_ENFORCED');

        String soql = String.join(soqlParts, ' ');

        // Execute with security enforcement (sharing + FLS)
        try {
            return Database.query(soql);
        } catch (Exception e) {
            throw new SearchException('Search query failed: ' + e.getMessage());
        }
    }

    private static Schema.SObjectType resolveObject(String objectApiName) {
        String lower = objectApiName.toLowerCase();
        Map<String, Schema.SObjectType> globalMap = Schema.getGlobalDescribe();
        for (String key : globalMap.keySet()) {
            if (key.toLowerCase() == lower) {
                return globalMap.get(key);
            }
        }
        return null;
    }

    private static Map<String, Schema.SObjectField> buildFieldMap(Schema.SObjectType objType) {
        Map<String, Schema.SObjectField> result = new Map<String, Schema.SObjectField>();
        Map<String, Schema.SObjectField> schemaFields = objType.getDescribe().fields.getMap();
        for (String key : schemaFields.keySet()) {
            result.put(key.toLowerCase(), schemaFields.get(key));
        }
        return result;
    }

    private static String formatValue(Object value) {
        if (value == null) {
            return 'NULL';
        }
        if (value instanceof String) {
            return "'" + String.escapeSingleQuotes((String) value) + "'";
        }
        if (value instanceof Boolean) {
            return (Boolean) value ? 'true' : 'false';
        }
        if (value instanceof Date) {
            return ((Date) value).format('yyyy-MM-dd');
        }
        if (value instanceof DateTime) {
            return ((DateTime) value).format('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'');
        }
        if (value instanceof Integer) {
            return String.valueOf(value);
        }
        if (value instanceof Long) {
            return String.valueOf(value);
        }
        if (value instanceof Decimal) {
            return String.valueOf(value);
        }
        if (value instanceof Double) {
            return String.valueOf(value);
        }
        if (value instanceof Currency) {
            return String.valueOf((Decimal) value);
        }
        // Fallback: treat as a quoted, escaped string
        return "'" + String.escapeSingleQuotes(String.valueOf(value)) + "'";
    }
}
```

**Summary of fixes:**

| Bug | Fix |
|---|---|
| `StringBuilder` doesn't exist in Apex | Replaced with `List<String>` + `String.join()` |
| `Map.entrySet()` / `Map.Entry` don't exist in Apex | Rewrote `buildFieldMap` to iterate `keySet()` |
| `DescribeFieldResult.isReadable()` doesn't exist | Changed to `isAccessible()` (the correct FLS check) |
| `''` is not a valid Apex string escape | Used `\'` for literal single quotes in the DateTime format pattern |

