public class AccountOnboardingService {

    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<fflib_ISObjectDomain> {
                new fflib_SObjectDomain('Account'),
                new fflib_SObjectDomain('Contact')
            }
        );

        // Phase 1 – queue all Accounts, then insert so their Ids are populated
        List<SObject> accountSobjs = new List<SObject>();
        List<Account> accounts = new List<Account>();
        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account acc = new Account(Name = accountName);
            accounts.add(acc);
            accountSobjs.add(acc);
        }
        uow.addSObjects(accountSobjs);
        uow.commitWork();

        // Phase 2 – queue all Contacts with the resolved AccountId, then insert
        List<SObject> contactSobjs = new List<SObject>();
        for (Account acc : accounts) {
            List<String> lastNames = contactLastNamesByAccountName.get(acc.Name);
            if (lastNames != null) {
                for (String lastName : lastNames) {
                    Contact con = new Contact(LastName = lastName, AccountId = acc.Id);
                    contactSobjs.add(con);
                }
            }
        }

        if (!contactSobjs.isEmpty()) {
            uow.addSObjects(contactSobjs);
            uow.commitWork();
        }

        return accounts;
    }
}
