public class AccountRatingService {

    // ------------------------------------------------------------------
    // Queueable wrapper – enqueued once per trigger execution
    // ------------------------------------------------------------------
    public class RecalcJob implements Queueable {
        private final Set<Id> accountIds;

        public RecalcJob(Set<Id> accountIds) {
            this.accountIds = accountIds;
        }

        public void execute(QueueableContext context) {
            recalculate(accountIds);
        }
    }

    // ------------------------------------------------------------------
    // Public entry-point called from the trigger
    // ------------------------------------------------------------------
    public static void enqueue(Set<Id> accountIds) {
        System.enqueueJob(new RecalcJob(accountIds));
    }

    // ------------------------------------------------------------------
    // Core logic – safe to call synchronously in unit tests
    // ------------------------------------------------------------------
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Fetch all open opportunities for the affected accounts in one SOQL
        Map<Id, List<Opportunity>> openOppsByAccount = new Map<Id, List<Opportunity>>();
        for (Opportunity opp : [
            SELECT Id, AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
        ]) {
            if (!openOppsByAccount.containsKey(opp.AccountId)) {
                openOppsByAccount.put(opp.AccountId, new List<Opportunity>());
            }
            openOppsByAccount.get(opp.AccountId).add(opp);
        }

        // Determine the correct rating for each account
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            String rating = deriveRating(openOppsByAccount.get(accountId));
            accountsToUpdate.add(new Account(Id = accountId, Rating = rating));
        }

        if (!accountsToUpdate.isEmpty()) {
            upsert accountsToUpdate;
        }
    }

    // ------------------------------------------------------------------
    // Rating derivation (pure function – easy to unit-test)
    // ------------------------------------------------------------------
    private static String deriveRating(List<Opportunity> openOpps) {
        if (openOpps == null || openOpps.isEmpty()) {
            return 'Cold';
        }

        for (Opportunity opp : openOpps) {
            if (opp.Amount != null && opp.Amount >= 100000) {
                return 'Hot';
            }
        }

        return 'Warm';
    }
}
