    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        Map<String, Id> firstContactByEmail = new Map<String, Id>();
        if (contacts != null) {
            for (Contact c : contacts) {
                if (String.isBlank(c.Email)) {
                    continue;
                }
                String key = c.Email.trim().toLowerCase();
                if (String.isBlank(key)) {
                    continue;
                }
                if (!firstContactByEmail.containsKey(key)) {
                    firstContactByEmail.put(key, c.Id);
                }
            }
        }

        List<Id> results = new List<Id>();
        if (leads != null) {
            for (Lead l : leads) {
                Id matchedId = null;
                if (!String.isBlank(l.Email)) {
                    String key = l.Email.trim().toLowerCase();
                    if (!String.isBlank(key)) {
                        matchedId = firstContactByEmail.get(key);
                    }
                }
                results.add(matchedId);
            }
        }
        return results;
    }
