            // Governor limit: 50 System.enqueueJob calls per transaction.
            // Chunk into batches of 50 so 200 cases = 4 enqueues (well within limit).
            Integer batchSize = 50;
            for (Integer i = 0; i < eligibleCaseIds.size(); i += batchSize) {
                Integer endIndex = Math.min(i + batchSize, eligibleCaseIds.size());
                System.enqueueJob(new CaseSurveyJob(eligibleCaseIds.sublist(i, endIndex)));
            }
        }
    }
}
