public class CaseSurveyJob implements Queueable {
    private final List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext qc) {
        // Re-query for fresh data; the job may run minutes after the trigger fired.
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM Case
            WHERE Id IN :caseIds
        ];

        for (Case c : cases) {
            try {
                // Defensive guard: skip if the case was reopened or lost its contact
                if (!c.IsClosed || c.ContactId == null) {
                    continue;
                }

                insert new Task(
                    WhatId       = c.Id,
                    WhoId        = c.ContactId,
                    Subject      = 'CSAT survey: ' + c.CaseNumber,
                    ActivityDate = Date.today().addDays(2),
                    Status       = 'Not Started'
                );
            } catch (Exception e) {
                // Isolate failures: one bad record must not block the rest of the batch.
                // In production, replace with a custom __Log__ insert or Platform Event.
                System.debug(LoggingLevel.ERROR,
                    'CaseSurveyJob: failed for Case ' + c.Id + ' — ' + e.getMessage());
            }
        }
    }
}
