```apex
public class AccountCountrySync {

    /**
     * Bulk-safe after-update handler.
     *
     * For every Account whose BillingCountry changed, sets MailingCountry on
     * its contacts to the new BillingCountry — but only for contacts whose
     * MailingCountry is blank or still equals the *old* BillingCountry.
     *
     * • Single SOQL scoped to the changed AccountIds (no unbounded scan).
     * • Single DML (update) at the end.
     * • No SOQL / DML inside loops.
     *
     * Uses SObject.get / SObject.put for country fields so the class
     * compiles even in orgs where the field is absent (returns null → no-op).
     */
    public static void handleUpdate() {

        // ── 1. Identify accounts whose BillingCountry actually changed ────
        Map<Id, String> oldCountry = new Map<Id, String>();
        Map<Id, String> newCountry = new Map<Id, String>();

        for (Integer i = 0; i < Trigger.New.size(); i++) {
            String o = (String) Trigger.Old[i].get('BillingCountry');
            String n = (String) Trigger.New[i].get('BillingCountry');

            if (n != o) {
                oldCountry.put(Trigger.New[i].Id, o);
                newCountry.put(Trigger.New[i].Id, n);
            }
        }

        if (oldCountry.isEmpty()) {
            return;
        }

        // ── 2. One SOQL – only contacts of the affected accounts ──────────
        List<Contact> contacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :oldCountry.keySet()
        ];

        // ── 3. Filter in memory ───────────────────────────────────────────
        List<Contact> toUpdate = new List<Contact>();

        for (Contact c : contacts) {
            String prevCountry = oldCountry.get(c.AccountId);
            String currCountry = newCountry.get(c.AccountId);

            String mailCountry = (String) c.get('MailingCountry');

            Boolean isBlank    = (mailCountry == null || mailCountry == '');
            Boolean matchesOld = (mailCountry == prevCountry);

            if (isBlank || matchesOld) {
                c.put('MailingCountry', currCountry);
                toUpdate.add(c);
            }
        }

        // ── 4. One DML ────────────────────────────────────────────────────
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
