import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } */
    @api lines = [];

    showError = false;

    handleClick(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'reset') {
            this.handleReset();
        } else if (action === 'submit') {
            this.handleSubmit();
        }
    }

    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach((editor) => editor.reset());
    }

    handleSubmit() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        let allValid = true;

        // Validate every editor so all invalid lines display their errors
        editors.forEach((editor) => {
            if (!editor.validate()) {
                allValid = false;
            }
        });

        if (allValid) {
            this.showError = false;
            const resultLines = editors.map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', { detail: { lines: resultLines } })
            );
        } else {
            this.showError = true;
        }
    }
}
