```js
import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _value;
    _options;
    _activeIndex = -1;

    @api get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this._updateActiveIndex();
    }

    @api get options() {
        return this._options;
    }
    set options(val) {
        this._options = val;
        this._updateActiveIndex();
    }

    get renderedOptions() {
        if (!this._options) return [];
        return this._options.map((opt, i) => ({
            id: `${this.id}-opt-${i}`,
            label: opt.label,
            value: opt.value,
            index: i,
            isSelected: opt.value === this._value
        }));
    }

    get ariaActivedescendant() {
        if (!this._options || this._options.length === 0 || this._activeIndex < 0) {
            return undefined;
        }
        return `${this.id}-opt-${this._activeIndex}`;
    }

    _updateActiveIndex() {
        if (!this._options || this._options.length === 0) {
            this._activeIndex = -1;
            return;
        }
        const idx = this._options.findIndex((opt) => opt.value === this._value);
        this._activeIndex = idx >= 0 ? idx : 0;
    }

    handleKeydown(event) {
        const key = event.key;
        const validKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (!validKeys.includes(key)) return;

        event.preventDefault();

        if (!this._options || this._options.length === 0) return;

        switch (key) {
            case 'ArrowDown':
                if (this._activeIndex < this._options.length - 1) {
                    this._activeIndex++;
                }
                break;
            case 'ArrowUp':
                if (this._activeIndex > 0) {
                    this._activeIndex--;
                }
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectActive();
                break;
        }
    }

    handleOptionClick(event) {
        const index = parseInt(event.currentTarget.dataset.index, 10);
        this._activeIndex = index;
        if (this._value !== this._options[index].value) {
            this._value = this._options[index].value;
            this.dispatchEvent(
                new CustomEvent('change', { detail: { value: this._value } })
            );
        }
    }

    _selectActive() {
        if (this._activeIndex < 0 || this._activeIndex >= this._options.length) return;
        if (this._value !== this._options[this._activeIndex].value) {
            this._value = this._options[this._activeIndex].value;
            this.dispatchEvent(
                new CustomEvent('change', { detail: { value: this._value } })
            );
        }
    }
}
