public class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // --- Validation (all checks before any DML) ---

        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id must not be null.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Percent map must not be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException(
                    'All percentages must be greater than zero. Invalid entry for GAU: ' + gauId
                );
            }
            totalPercent += pct;
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'Total percentage (' + totalPercent + ') exceeds 100.'
            );
        }

        // Validate GAUs are active
        Set<Id> gauIds = new Set<Id>(percentByGauId.keySet());
        Map<Id, npsp__General_Accounting_Unit__c> gauMap = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, Name, npsp__Active__c FROM npsp__General_Accounting_Unit__c WHERE Id IN :gauIds]
        );

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauMap.get(gauId);
            if (gau == null || !gau.npsp__Active__c) {
                throw new AllocationException(
                    'GAU is inactive or not found: ' + (gau != null ? gau.Name : gauId)
                );
            }
        }

        // --- Fetch current opportunity amount ---
        Decimal oppAmount = [SELECT Amount FROM Opportunity WHERE Id = :opportunityId].Amount;
        if (oppAmount == null) {
            oppAmount = 0;
        }

        // --- Delete existing allocations for this opportunity ---
        List<npsp__Allocation__c> existingAllocs = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocs.isEmpty()) {
            Delete existingAllocs;
        }

        // --- Build and insert new allocations ---
        // Setting npsp__Percent__c allows NPSP's standard recalculation
        // (triggered on Opportunity.Amount change) to keep amounts correct.
        List<npsp__Allocation__c> newAllocs = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            newAllocs.add(new npsp__Allocation__c(
                npsp__Opportunity__c              = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c                 = pct,
                npsp__Amount__c                  = oppAmount * pct / 100
            ));
        }

        Insert newAllocs;
        return newAllocs;
    }
}
```

**What changed:** Replaced the invalid `Map.entrySet()` / `Map.Entry` iteration with Apex's standard pattern of iterating over `keySet()` and calling `.get(key)` for each value. Everything else remains the same.

