```apex
public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Gather unique IDs for bulk queries
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId != null) oppIds.add(req.opportunityId);
            if (req.contactId != null) contactIds.add(req.contactId);
        }

        // SOQL 1: Opportunities (amount + primary contact for validation)
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // SOQL 2: Contacts (name for reference)
        Map<Id, Contact> contactMap = new Map<Id, Contact>(
            [SELECT Id, Name
             FROM Contact
             WHERE Id IN :contactIds]
        );

        // SOQL 3: Existing OpportunityContactRoles for the relevant pairs
        Map<String, OpportunityContactRole> ocrMap = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, ContactId, OpportunityId, Role
            FROM OpportunityContactRole
            WHERE ContactId IN :contactIds
              AND OpportunityId IN :oppIds
        ]) {
            ocrMap.put(ocr.OpportunityId + '|' + ocr.ContactId, ocr);
        }

        // SOQL 4: Existing Partial Soft Credits for the relevant pairs
        Map<String, npsp__Partial_Soft_Credit__c> pscMap =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c,
                   npsp__Amount__c, npsp__Role_Name__c,
                   npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            pscMap.put(psc.npsp__Opportunity__c + '|' + psc.npsp__Contact__c, psc);
        }

        // ─── VALIDATION (all before any DML) ───────────────────────────────
        for (SoftCreditRequest req : requests) {
            if (req.amount == null) {
                throw new SoftCreditException(
                    'Amount is required for opportunity ' + req.opportunityId
                    + ' / contact ' + req.contactId + '.');
            }
            if (req.amount <= 0) {
                throw new SoftCreditException(
                    'Amount must be positive for opportunity ' + req.opportunityId
                    + ' / contact ' + req.contactId + '.');
            }

            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + req.opportunityId + '.');
            }

            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId
                    + ' is the primary contact of opportunity ' + req.opportunityId
                    + '; partial soft credits are not allowed for the primary contact.');
            }

            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount (' + req.amount
                    + ') exceeds opportunity amount (' + opp.Amount
                    + ') for opportunity ' + req.opportunityId + '.');
            }
        }

        // ─── BUILD OPPORTUNITY CONTACT ROLES ────────────────────────────────
        // Reuse existing OCR (updating its Role) or create a new one.
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        Map<String, Id> ocrIdMap = new Map<String, Id>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '|' + req.contactId;

            if (ocrMap.containsKey(key)) {
                OpportunityContactRole ocr = ocrMap.get(key);
                ocr.Role = req.role;
                ocrsToUpsert.add(ocr);
                ocrIdMap.put(key, ocr.Id);
            } else {
                OpportunityContactRole ocr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrsToUpsert.add(ocr);
                // Id populated after upsert
            }
        }

        // DML 1: upsert all OCR changes in a single statement
        if (!ocrsToUpsert.isEmpty()) {
            upsert ocrsToUpsert;
            for (OpportunityContactRole ocr : ocrsToUpsert) {
                ocrIdMap.put(ocr.OpportunityId + '|' + ocr.ContactId, ocr.Id);
            }
        }

        // ─── BUILD PARTIAL SOFT CREDITS ─────────────────────────────────────
        // Update existing PSC or create a new one; link to the OCR.
        List<npsp__Partial_Soft_Credit__c> pscsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '|' + req.contactId;
            Id ocrId = ocrIdMap.get(key);

            npsp__Partial_Soft_Credit__c psc;
            if (pscMap.containsKey(key)) {
                psc = pscMap.get(key);
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Contact_Role_ID__c = String.valueOf(ocrId);
            } else {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = String.valueOf(ocrId)
                );
            }
            pscsToUpsert.add(psc);
        }

        // DML 2: upsert all soft credit changes in a single statement
        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }
    }
}
```

**Changes made:**

1. **`Contact__c` → `ContactId`** and **`Opportunity__c` → `OpportunityId`** — On `OpportunityContactRole`, the standard lookup fields are `ContactId` and `OpportunityId` (no `__c` suffix), not custom-style names.

2. **Removed `npsp__Contact_Name__c`** from the soft credit inserts/updates — this field is a formula/rollup in NPSP (auto-populated) and is not writeable, so attempting to set it causes a compile error.

**Governor-limit accounting (200 requests):**

| Resource | Count | Limit |
|----------|-------|-------|
| SOQL queries | 4 (Opportunity, Contact, OCR, PSC) | ≤ 4 ✓ |
| DML statements | 2 (upsert OCRs, upsert PSCs) | ≤ 4 ✓ |

