public class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect all contact IDs (both children and parents)
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            if (childId != null) {
                allContactIds.add(childId);
            }
            Id parentId = parentIdByChildId.get(childId);
            if (parentId != null) {
                allContactIds.add(parentId);
            }
        }

        if (allContactIds.isEmpty()) {
            return;
        }

        // 1 SOQL: find all existing relationships involving any of these contacts
        List<npe4__Relationship__c> existingRels = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
               OR npe4__RelatedContact__c IN :allContactIds
        ];

        // Build a set of canonical pairs to detect existing relationships in either direction
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : existingRels) {
            existingPairs.add(canonicalPair(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        // Build new relationship records, skipping pairs that already have a relationship
        List<npe4__Relationship__c> newRels = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null) {
                continue;
            }

            if (existingPairs.contains(canonicalPair(childId, parentId))) {
                continue;
            }

            newRels.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        // 1 DML: insert all new relationships (NPSP reciprocal trigger creates the second record)
        if (!newRels.isEmpty()) {
            insert newRels;
        }
    }

    private static String canonicalPair(Id a, Id b) {
        String s1 = String.valueOf(a);
        String s2 = String.valueOf(b);
        return s1 < s2 ? s1 + '|' + s2 : s2 + '|' + s1;
    }
}
