public with sharing class EmployeeDirectoryService {

    public static List<FB_Employee__c> getDirectory() {
        // If the running user cannot access the object at all, return an empty list
        if (!FB_Employee__c.sObjectType.getDescribe().isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Build the field list, including only custom fields the user can read
        List<String> fields = new List<String>{ 'Id', 'Name' };

        if (FB_Employee__c.Department__c.getDescribe().isReadable()) {
            fields.add('Department__c');
        }
        if (FB_Employee__c.Salary__c.getDescribe().isReadable()) {
            fields.add('Salary__c');
        }
        if (FB_Employee__c.Personal_Email__c.getDescribe().isReadable()) {
            fields.add('Personal_Email__c');
        }

        // Dynamic SOQL executes within the 'with sharing' context,
        // so only records the user has access to via sharing rules are returned.
        String soql = 'SELECT ' + String.join(fields, ', ')
            + ' FROM FB_Employee__c ORDER BY Name ASC';

        return (List<FB_Employee__c>) Database.query(soql);
    }
