public class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert,
                                                 TriggerAction.AfterUpdate,
                                                 TriggerAction.AfterDelete,
                                                 TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = collectAccountIds(triggerNew);
        recalculateAndUpdate(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : triggerNew) {
            Case c = (Case) so;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        for (SObject so : triggerOld) {
            Case c = (Case) so;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        recalculateAndUpdate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = collectAccountIds(triggerOld);
        recalculateAndUpdate(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = collectAccountIds(triggerNew);
        recalculateAndUpdate(accountIds);
    }

    private Set<Id> collectAccountIds(List<SObject> cases) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : cases) {
            Case c = (Case) so;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        return accountIds;
    }

    private void recalculateAndUpdate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Query 1 of max 2: count open cases per affected account
        Map<Id, Decimal> openCounts = new Map<Id, Decimal>();
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) cnt
            FROM Case
            WHERE AccountId IN :accountIds
              AND IsClosed = false
              AND IsDeleted = false
            GROUP BY AccountId
        ]) {
            openCounts.put((Id) ar.get('AccountId'), (Decimal) ar.get('cnt'));
        }

        // Build the update list; accounts with zero open cases get 0, not null
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            Decimal cnt = openCounts.get(accountId);
            if (cnt == null) {
                cnt = 0;
            }
            accountsToUpdate.add(new Account(Id = accountId, FB_Open_Case_Count__c = cnt));
        }

        // DML 1 of max 1: update affected accounts
        update accountsToUpdate;
    }
}
